class _RestorationCounterPageState extends State<RestorationCounterPage>
    with RestorationMixin {
  final RestorableInt _counter = RestorableInt(0);

  // 1. Provide a unique restoration ID.
  @override
  String? get restorationId => 'counter_page';

  // 2. Register your restorable properties.
  @override
  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {
    registerForRestoration(_counter, 'counter_value');
  }

  // Don't forget to dispose of your properties!
  @override
  void dispose() {
    _counter.dispose();
    super.dispose();
  }

  void _incrementCounter() {
    setState(() {
      _counter.value++;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Counter Restoration')),
      body: Center(
        child: Text('Count: ${_counter.value}', // Access the data via .value
            style: Theme.of(context).textTheme.headlineMedium),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: _incrementCounter,
        child: Icon(Icons.add),
      ),
    );
  }
}
